def compare_f01(packet,context):
 observed=packet.get('observed_frame') or {};required=packet.get('required_frame') or {};results={}
 for field in FIELDS:
  if field=='BRAIN_input_compatibility' and packet.get('selected_owner')!='BRAIN':
   state='unknown' if packet.get('selected_owner') in [None,'TBD',''] else 'unobserved'
  else:state=state_of(observed.get(field),required.get(field),field in ['L1_revision','template_revision','extractor_version'])
  results[field]=result(state,observed.get(field) if state=='supported_synthetic_condition' else None)
 scope_states=[v['state'] for v in results.values()]
 if packet.get('selected_owner')!='BRAIN':scope_states.append('unknown')
 state=aggregate(scope_states);return {'input_results':results,'selected_scope_result':result(state,observed.get('scope') if state=='supported_synthetic_condition' else None),'reference_only_inputs':result('known',packet.get('reference_only',[])),**common(context)}

def elements(template):
 records=[]
 if template is None or not isinstance(template.get('raw_utf8'),str):return records
 for line,text in enumerate(template['raw_utf8'].splitlines(),1):
  try:value=json.loads(text)
  except (ValueError,TypeError):value={'id':'unparsed-line-'+str(line),'kind':'unparsed','meaning':text}
  records.append({'element':value,'span':{'start_line':line,'end_line':line}})
 return records

def applicable(element,inputs):
 if element.get('requires_screen') is True:
  screen=inputs.get('screen')
  if screen in [None,'TBD','']:return 'unknown'
  return 'yes' if screen is True else 'no'
 return 'yes'

def compare_f02(packet,context):
 atom_results={};rows={};template=packet.get('original_template') or {};contract=packet.get('independent_extractor_contract') or {};inputs=packet.get('applicability_input') or {};candidates=packet.get('candidate_atoms') or [];records=packet.get('mechanical_candidate_records') or {}
 for entry in elements(template):
  original=entry['element'];identity=original['id'];applies=applicable(original,inputs)
  if applies=='no' and na_valid((packet.get('reasoned_NA') or {}).get(identity),template.get('revision')):continue
  matches=[atom for atom in candidates if atom_matches(atom,identity)];states=[]
  if applies=='unknown':states.append('unknown')
  if len(matches)==0:states.append('missing')
  elif len(matches)!=1 or len(matches[0].get('source_element_ids',[identity]))!=1:states.append('conflict')
  if states:state=aggregate(states);atom_results[identity]=result(state);rows[identity]=result(state);continue
  atom=matches[0];content=atom.get('content') or {};material=records.get(identity)
  expected={'source_element_id':identity,'source_span':entry['span'],'template_revision':template.get('revision'),'applicability':inputs,'kind':original.get('kind'),'meaning':original.get('meaning'),'extractor_identity':contract.get('identity'),'extractor_version':contract.get('version')}
  states=[state_of(content.get(field),value,field in ['template_revision','extractor_version']) for field,value in expected.items()]
  states += [state_of(atom.get('semantic_digest'),value_digest(content)),state_of(atom.get('extractor_version_digest'),value_digest(contract))]
  if text_digest(template.get('raw_utf8',''))!=template.get('sha256'):states.append('conflict')
  if material is None:states.append('conflict' if (packet.get('human_summary_candidates') or {}).get(identity) else 'missing')
  else:
   for field,value in {'source_element_id':identity,'candidate_ref':atom.get('atom_id'),'content_sha256':value_digest(content),'extractor_identity':contract.get('identity'),'extractor_version':contract.get('version'),'input_template_sha256':template.get('sha256'),'kind':'synthetic_mechanical_candidate_record','execution_state':'not_executed_fixture_only'}.items():states.append(state_of(material.get(field),value,field=='extractor_version'))
  state=aggregate(states);atom_results[identity]=result(state,atom.get('atom_id') if state=='supported_synthetic_condition' else None)
  row=atom.get('candidate_row') or {};row_state=state
  if row_state=='supported_synthetic_condition':row_state=aggregate([state_of(row.get('atom_ref'),atom.get('atom_id')),state_of(row.get('ledger_contract'),packet.get('independent_ledger_contract'))])
  rows[identity]=result(row_state,row.get('ledger_contract') if row_state=='supported_synthetic_condition' else None)
 return {'atom_results':atom_results,'candidate_row_results':rows,**common(context)}

def compare_f03(packet,context):
 template=packet.get('original_template') or {};inputs=packet.get('applicability_input') or {};dispositions={};gaps=[];atoms=packet.get('candidate_atoms') or []
 for entry in elements(template):
  original=entry['element'];identity=original['id'];applies=applicable(original,inputs);matches=[atom for atom in atoms if atom_matches(atom,identity)];kind=None
  if original.get('kind') not in KINDS:kind='unsupported_element'
  elif original.get('meaning') in [None,'']:kind='empty'
  elif original.get('meaning')=='TBD':kind='placeholder'
  elif applies=='unknown':kind='applicability_unknown'
  elif applies=='no':
   na=(packet.get('reasoned_NA') or {}).get(identity)
   if na_valid(na,template.get('revision')):dispositions[identity]={'kind':'reasoned_not_applicable','reason':na['reason']};continue
   kind='non_applicability_unqualified'
  elif len(matches)==0:kind='uncovered'
  elif len(matches)>1:kind='duplicate'
  elif len(matches[0].get('source_element_ids',[identity]))!=1:kind='compound'
  elif (matches[0].get('content') or {}).get('meaning')!=original.get('meaning'):kind='content_conflict'
  else:
   atom=matches[0];content=atom.get('content') or {};checks={'source_element_id':identity,'source_span':entry['span'],'template_revision':template.get('revision'),'kind':original.get('kind')}
   if original.get('requires_screen') is True:checks['applicability']=inputs
   if any(not same(content.get(k),v) for k,v in checks.items()) or atom.get('semantic_digest')!=value_digest(content):kind='candidate_metadata_conflict'
  if kind:
   dispositions[identity]={'kind':'gap','gap_kind':kind};gaps.append({'element_id':identity,'kind':kind,'source_span':entry['span'],'occurrence_count':len(matches) if kind=='duplicate' else 1})
  else:dispositions[identity]={'kind':'atom','atom_id':matches[0]['atom_id']}
 if not isinstance(template.get('raw_utf8'),str) or template.get('raw_utf8')=='':gaps.append({'element_id':None,'kind':'template_source_missing','source_span':None,'occurrence_count':1})
 elif text_digest(template['raw_utf8'])!=template.get('sha256'):gaps.append({'element_id':None,'kind':'source_digest_conflict','source_span':None,'occurrence_count':1})
 return {'element_dispositions':dispositions,'gaps':gaps,'fixture_content_complete':len(gaps)==0,**common(context)}

def compare_n01(packet,context):
 sources=packet.get('result_sources') or [];frame=packet.get('input_frame') or {};template=packet.get('original_template') or {};state='supported_synthetic_condition'
 if packet.get('independence_qualification')!='known_in_synthetic_fixture':state='unknown'
 elif len(sources)!=2:state='missing'
 elif sources[0].get('run_id') in [None,'','TBD'] or sources[0].get('run_id')==sources[1].get('run_id'):state='unknown'
 elif frame.get('template_revision')!=template.get('revision'):state='stale'
 elif text_digest(template.get('raw_utf8',''))!=template.get('sha256'):state='conflict'
 else:
  input_digest=value_digest({'template':template,'input':frame});states=[]
  for source in sources:
   states.extend([state_of(source.get('input_sha256'),input_digest),state_of(source.get('semantic_digest'),value_digest(source.get('content')))])
  states.append(state_of(sources[0].get('semantic_digest'),sources[1].get('semantic_digest')));state=aggregate(states)
 held=packet.get('held_out_source');gap=None;held_gaps=[]
 if held is not None:
  if not isinstance(held.get('raw_utf8'),str) or held.get('raw_utf8')=='':held_gaps.append({'element_id':None,'kind':'template_source_missing','template_revision':held.get('revision'),'source_span':None})
  for entry in elements(held):
   kind=None;scope_state=state_of(held.get('scope'),frame.get('scope'))
   if scope_state!='supported_synthetic_condition':kind='scope_'+scope_state
   elif held.get('revision') in [None,'','TBD']:kind='source_revision_unknown' if held.get('revision')=='TBD' else 'source_revision_missing'
   elif text_digest(held.get('raw_utf8',''))!=held.get('sha256'):kind='source_digest_conflict'
   elif entry['element'].get('kind') not in KINDS:kind='unsupported_element'
   if kind:held_gaps.append({'element_id':entry['element']['id'],'kind':kind,'template_revision':held.get('revision'),'source_span':entry['span']})
  gap=held_gaps[0] if len(held_gaps)==1 else held_gaps if held_gaps else None
 return {'comparison_result':result(state,'equal_for_this_fixture_input_only' if state=='supported_synthetic_condition' else None),'general_determinism_guaranteed':False,'all_templates_supported':False,'held_out_gap':gap,**common(context)}

def compare_b01(packet,context):
 returns=[]
 for field,owner in [('template_meaning','CORE009/template-owner'),('ledger_pair_contract','040-compatible-contract-owner'),('OS_observation','OS-operation-owner')]:
  value=packet.get(field);value='missing' if value is None else value
  if value!='known':returns.append({'owner':owner,'reason':field+':'+value})
 return {'owner_return_candidates':returns,'requires_025_026_completion_to_author':False,**common(context)}

def compare_source_attributes(actual,required):
 actual=actual or {};required=required or {};fields={}
 for key in ['identity','revision','scope','owner']:
  state=state_of(actual.get(key),required.get(key),key=='revision');fields[key]=result(state,actual.get(key) if state=='supported_synthetic_condition' else None)
 state=aggregate([v['state'] for v in fields.values()])
 return {'attribute_results':fields,'attribute_comparison':result(state,'attributes_compared_only' if state=='supported_synthetic_condition' else None),'actual_qualification_established':False,'qualification_provider':result('unknown')}
